class Solution {
public:
    int maxNumberOfApples(std::vector<int>& weight) {
        std::sort(weight.begin(), weight.end());
        int total = 0, count = 0;
        for (int w : weight) {
            if (total + w <= 5000) {
                total += w;
                count++;
            } else {
                break;
            }
        }
        return count;
    }
};

class Solution {
    public int maxNumberOfApples(int[] weight) {
        java.util.Arrays.sort(weight);
        int total = 0, count = 0;
        for (int w : weight) {
            if (total + w <= 5000) {
                total += w;
                count++;
            } else {
                break;
            }
        }
        return count;
    }
}

var maxNumberOfApples = function(weight) {
    weight.sort((a, b) => a - b);
    let total = 0, count = 0;
    for (const w of weight) {
        if (total + w <= 5000) {
            total += w;
            count++;
        } else {
            break;
        }
    }
    return count;
};
